import subprocess, random, time
MOD=10**9+7

def ref(n):
    # independent recursive fast doubling
    if n==0: return (0,1)
    a,b = ref(n>>1)
    c = a*((2*b-a)%MOD)%MOD
    d = (a*a+b*b)%MOD
    if n&1: return (d,(c+d)%MOD)
    return (c,d)

ok=True
for n in [0,1,2,3,10,100,1000,12345,10**6,10**12,10**18-1]:
    got=int(subprocess.check_output(['python3','fibmod.py',str(n)]))
