import time, random
MOD=10**9+7

def fd(n, mod=MOD):
    a,b=0,1
    for ch in bin(n)[2:]:
        c=a*((2*b-a)%mod)%mod
        d=(a*a+b*b)%mod
        if ch=='0':
            a,b=c,d
        else:
            a,b=d,(c+d)%mod
    return a

cand=2*(MOD+1)
x=cand
factors={}
d=2
while d*d<=x:
    while x%d==0:
        factors[d]=factors.get(d,0)+1
        x//=d
    d += 1 if d==2 else 2
if x>1: factors[x]=factors.get(x,0)+1
print('candidate', cand, 'factors', factors)

def is_period(k):
    return fd(k)==0 and fd(k+1)==1

period=cand
for p in factors:
    while period%p==0 and is_period(period//p):
        period//=p
print('period', period)
print('period_is_period', is_period(period))

# correctness of reduction on samples
random.seed(1)
for n in [0,1,2,10,10**18,10**18-1]+[random.randrange(10**18+1) for _ in range(20)]:
    if fd(n)!=fd(n%period):
        print('BAD', n); break
else:
    print('reduction correct')

ns=[random.randrange(10**18+1) for _ in range(20000)]
for name, fn in [('full', fd), ('reduced', lambda n: fd(n%period))]:
    t=time.perf_counter()
    s=0
    for n in ns: s+=fn(n)
    dt=time.perf_counter()-t
    print(name, dt, 'per_call', dt/len(ns), 'checksum', s%MOD)
